pipeline {
  agent { label 'mac' }                 // where to run

  options {                             // rules for the whole run
    timeout(time: 45, unit: 'MINUTES')
    disableConcurrentBuilds()
    buildDiscarder(logRotator(numToKeepStr: '20', artifactNumToKeepStr: '5'))
    timestamps()
  }

  parameters {                          // the "Build with Parameters" form
    string(name: 'BRANCH', defaultValue: 'develop', description: 'Branch to build')
    choice(name: 'ENV', choices: ['qa', 'uat', 'prod'], description: 'Backend')
    booleanParam(name: 'UPLOAD', defaultValue: false, description: 'Send to testers')
  }

  environment {                         // variables for every step
    LANG = 'en_US.UTF-8'
    API_KEY = credentials('asc-api-key-id')   // pulled from the credential store, masked in logs
  }

  triggers { cron('H 2 * * 1-5') }      // optional: nightly

  stages {
    stage('Checkout') { steps { checkout scm } }
    stage('Build')    { steps { sh './build.sh' } }
    stage('Upload') {
      when { expression { params.UPLOAD } }   // run only when asked
      steps { sh './upload.sh' }
    }
  }

  post {                                // after the stages, whatever happened
    success { archiveArtifacts artifacts: 'build/**/*.ipa', fingerprint: true }
    failure { echo 'send a message here' }
    always  { cleanWs() }
  }
}

// app/build.gradle(.kts) idea: read signing from the environment, never from the repo
signingConfigs {
  release {
    storeFile file(System.getenv("KEYSTORE_FILE") ?: "missing.jks")
    storePassword System.getenv("KEYSTORE_PASSWORD")
    keyAlias System.getenv("KEY_ALIAS")
    keyPassword System.getenv("KEY_PASSWORD")
  }
}

pipeline {
  agent { label 'android' }
  options {
    timeout(time: 30, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '20', artifactNumToKeepStr: '5'))
    timestamps()
  }
  parameters {
    string(name: 'BRANCH', defaultValue: 'develop', description: 'Branch to build')
    choice(name: 'VARIANT', choices: ['Debug', 'Beta', 'Release'], description: 'Build type')
  }
  environment {
    ANDROID_HOME = '/Users/jenkins/Library/Android/sdk'   // where the SDK is on the agent
    GRADLE_OPTS  = '-Dorg.gradle.daemon=false -Dorg.gradle.jvmargs=-Xmx4g'
  }
  stages {
    stage('Checkout') { steps { checkout scm } }

    stage('Flutter module') {                 // only if the app embeds the Flutter module from source
      steps { dir('Flutter') { sh 'flutter pub get' } }
    }

    stage('Build') {
      steps {
        withCredentials([
          file(credentialsId: 'android-upload-keystore', variable: 'KEYSTORE_FILE'),
          string(credentialsId: 'android-keystore-pass', variable: 'KEYSTORE_PASSWORD'),
          string(credentialsId: 'android-key-alias', variable: 'KEY_ALIAS'),
          string(credentialsId: 'android-key-pass', variable: 'KEY_PASSWORD')
        ]) {
          sh './gradlew clean assembleRegular$VARIANT -PKEY_STORE_FILE="$KEYSTORE_FILE" -PSTORE_PASSWD="$KEYSTORE_PASSWORD" -PKEY_ALIAS="$KEY_ALIAS" -PKEY_PASSWD="$KEY_PASSWORD" -PVERSION_CODE=$BUILD_NUMBER --stacktrace'
        }
      }
    }
  }
  post {
    success {
      archiveArtifacts artifacts: 'app/build/outputs/**/*.apk, app/build/outputs/**/*.aab, app/build/outputs/mapping/**/mapping.txt',
        fingerprint: true, allowEmptyArchive: true
    }
  }
}

post {
  success { slackSend channel: '#mobile-builds', color: 'good',
    message: "iOS ${params.SCHEME} #${env.BUILD_NUMBER} from ${params.BRANCH} is ready: ${env.BUILD_URL}" }
  failure { slackSend channel: '#mobile-builds', color: 'danger',
    message: "iOS #${env.BUILD_NUMBER} failed at ${env.BUILD_URL}console" }
}
